ClinicalChunks.register("data/documents-003.js",[{"id":"documents-b804061d5465c77c3854","key":"v1-c9ccc21dfe2a3058|documents-b804061d5465c77c3854","module":"documents","moduleKey":"v1-c9ccc21dfe2a3058|documents","version":"v1-c9ccc21dfe2a3058","title":"医保智能监管「两库」规则速查","category":"医保管理","raw":{"fragment":"<div class=\"page\">\r\n<div class=\"doc-category\">【医保管理】</div>\r\n<div class=\"doc-title\">医保智能监管「两库」规则速查</div>\r\n<div class=\"doc-content\">【医保智能监管「两库」是什么】<br><br>知识库 —— 药品、医用耗材、医疗服务项目、疾病诊断、医保医师等基础信息，<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;以及这些项目对应的医保支付政策（限定支付范围、限定适应症、限定人群、限定等级医院）。<br>规则库 —— 医保经办机构据此设置的审核监控规则，医院端 HIS / 医保办按规则先做前置审核，<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;上传后医保端再跑一遍智能审核（事前提醒、事中审核、事后监管）。<br><br>一句话：知识库告诉你「这个项目医保怎么规定的」，规则库告诉你「什么情况会被判违规」。<br><br>──────────────────────────────<br>【一、最常见的规则类型（医生端要心里有数）】<br><br>1. 限定支付范围类<br>&nbsp;&nbsp; · 限适应症：如某些靶向药限特定基因突变或特定分期；某些中成药限特定证型<br>&nbsp;&nbsp; · 限人群：限儿童、限孕妇、限 65 岁以上、限工伤、限生育保险<br>&nbsp;&nbsp; · 限二线用药：一线治疗失败或不能耐受方可使用<br>&nbsp;&nbsp; · 限医院等级：限二级及以上医疗机构、限三级医院<br>&nbsp;&nbsp; · 限处方权限：特殊使用级抗菌药物须经会诊、限高级职称医师<br><br>2. 频次 / 疗程类<br>&nbsp;&nbsp; · 复查频次：如 CT/MRI 每 90 天不超过 1 次（肿瘤随访除外，需 record 依据）<br>&nbsp;&nbsp; · 疗程上限：同一药品连续使用天数上限；超疗程需说明理由<br>&nbsp;&nbsp; · 同日重复：同一项目同一天重复开单<br><br>3. 诊断与项目不符类（最高发的扣款原因）<br>&nbsp;&nbsp; · 诊断与用药适应证不符（如无感染诊断用抗菌药物）<br>&nbsp;&nbsp; · 诊断与检查项目不符（如无相应症状/体征却开专项检查）<br>&nbsp;&nbsp; · 性别与项目不符（男性患者出现妇科项目）<br>&nbsp;&nbsp; · 年龄与项目不符（成人开儿童专用项目）<br>&nbsp;&nbsp; · 部位与手术编码不符、主诊断与主手术不匹配<br><br>4. 收费管理类<br>&nbsp;&nbsp; · 分解收费 / 重复收费（同一操作拆成多个项目、或已含在项目内的耗材另收）<br>&nbsp;&nbsp; · 超标准收费（超出当地医疗服务价格标准）<br>&nbsp;&nbsp; · 超医保支付标准（超出限价部分由患者自付需告知）<br>&nbsp;&nbsp; · 串换项目（用低价项目套高价项目收费）<br>&nbsp;&nbsp; · 打包项目重复计费<br><br>5. 住院管理类<br>&nbsp;&nbsp; · 分解住院（同一疾病短期内多次出入院）<br>&nbsp;&nbsp; · 挂床住院 / 低标准入院（无住院指征收住院）<br>&nbsp;&nbsp; · 超长住院、住院期间无诊疗记录<br>&nbsp;&nbsp; · 门诊可解决的收住院<br><br>──────────────────────────────<br>【二、医生端自查清单（开单 / 写病历时就做）】<br><br>□ 主要诊断写准：ICD 编码与实际病情一致，不用「待查」「不适」当主诊断<br>□ 用药前看一眼说明书适应证与医保限定支付范围是否吻合<br>□ 超说明书用药：必须有知情同意 + 病程记录写明理由<br>□ 检查有指征：申请单填写临床意义，病程记录里体现「为什么查」<br>□ 特殊级抗菌药物：会诊单、处方权限、用药前送检<br>□ 复查频次异常：在病程记录里写清复查理由（如症状变化、疗效评估）<br>□ 收费与实际操作一致：不多收、不拆收、不串换<br>□ 住院有指征：入院记录写清收住院理由，病程记录每日有内容<br>□ 出院带药不超量、不超疗程<br>□ 转科/转院有记录，不出现「空档日」<br><br>──────────────────────────────<br>【三、被智能审核拦截 / 事后追回时怎么办】<br><br>1. 先看拦截提示属于哪一类规则（限定支付范围？诊断不符？频次？收费？）<br>2. 备齐申诉材料：<br>&nbsp;&nbsp; · 病历（入院记录、首次病程、日常病程、出院小结）<br>&nbsp;&nbsp; · 支持性检验检查结果<br>&nbsp;&nbsp; · 会诊记录、知情同意书、超说明书用药审批<br>&nbsp;&nbsp; · 收费明细与操作记录对应关系<br>3. 申诉要点：说明「为什么必须这样做」，落到病历文字上——<br>&nbsp;&nbsp; 病历里没写 = 视为没有（这是医保审核的基本原则）<br>4. 时限：按当地医保局/医院医保办规定的申诉期限提交，逾期视为认可<br><br>──────────────────────────────<br>【四、提醒】<br><br>· 各地医保政策差异很大（目录、限价、规则阈值都不一样），<br>&nbsp;&nbsp;本条为通用框架，具体以【当地医保局最新政策 + 本院医保办口径】为准。<br>· 「两库」规则会随政策更新，建议每季度向医保办确认一次本院被拦截的 TOP 规则。<br><br>【依据】国家医保局《医疗保障经办机构智能审核和监控知识库、规则库管理办法（试行）》<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;及各地医保智能监管实施细则（通用框架整理）<br></div>\r\n\r\n</div>","css":"\r\n  @page { size: A4; margin: 0; }\r\n  * { box-sizing: border-box; }\r\n  body { font-family: \"宋体\", \"SimSun\", \"微软雅黑\", serif; margin: 0; padding: 0; color: #000; line-height: 1.8; font-size: 14px; }\r\n  .page { max-width: 210mm; min-height: 297mm; margin: 0 auto; padding: 18mm 20mm; background: white; page-break-after: always; }\r\n  .page:last-child { page-break-after: auto; }\r\n  .cover-title { text-align: center; font-size: 28px; font-weight: bold; margin-top: 80px; margin-bottom: 30px; letter-spacing: 6px; }\r\n  .cover-info { text-align: center; font-size: 16px; line-height: 2.5; color: #333; }\r\n  .doc-title { text-align: center; font-size: 22px; font-weight: bold; letter-spacing: 6px; margin-bottom: 20px; padding-bottom: 12px; border-bottom: 2px solid #000; }\r\n  .doc-category { text-align: center; font-size: 13px; color: #666; margin-bottom: 15px; }\r\n  .doc-content { font-size: 14px; line-height: 2; white-space: normal; word-wrap: break-word; font-family: \"宋体\", \"SimSun\", serif; }\r\n  .doc-footer { margin-top: 30px; padding-top: 10px; border-top: 1px dashed #999; font-size: 11px; color: #666; text-align: center; }\r\n  .no-print { display: block; }\r\n  @media print {\r\n    .no-print { display: none !important; }\r\n    .page { box-shadow: none; margin: 0; padding: 18mm 20mm; max-width: none; min-height: auto; }\r\n    body { margin: 0; padding: 0; }\r\n    .doc-title { font-size: 20px; }\r\n    .doc-content { font-size: 13px; line-height: 1.9; }\r\n  }\r\n  @media screen {\r\n    body { background: #e8e8e8; padding: 20px; }\r\n    .page { box-shadow: 0 0 15px rgba(0,0,0,0.15); margin-bottom: 20px; }\r\n  }\r\n","text":"【医保智能监管「两库」是什么】\n\n知识库 —— 药品、医用耗材、医疗服务项目、疾病诊断、医保医师等基础信息，\n        以及这些项目对应的医保支付政策（限定支付范围、限定适应症、限定人群、限定等级医院）。\n规则库 —— 医保经办机构据此设置的审核监控规则，医院端 HIS / 医保办按规则先做前置审核，\n        上传后医保端再跑一遍智能审核（事前提醒、事中审核、事后监管）。\n\n一句话：知识库告诉你「这个项目医保怎么规定的」，规则库告诉你「什么情况会被判违规」。\n\n──────────────────────────────\n【一、最常见的规则类型（医生端要心里有数）】\n\n1. 限定支付范围类\n   · 限适应症：如某些靶向药限特定基因突变或特定分期；某些中成药限特定证型\n   · 限人群：限儿童、限孕妇、限 65 岁以上、限工伤、限生育保险\n   · 限二线用药：一线治疗失败或不能耐受方可使用\n   · 限医院等级：限二级及以上医疗机构、限三级医院\n   · 限处方权限：特殊使用级抗菌药物须经会诊、限高级职称医师\n\n2. 频次 / 疗程类\n   · 复查频次：如 CT/MRI 每 90 天不超过 1 次（肿瘤随访除外，需 record 依据）\n   · 疗程上限：同一药品连续使用天数上限；超疗程需说明理由\n   · 同日重复：同一项目同一天重复开单\n\n3. 诊断与项目不符类（最高发的扣款原因）\n   · 诊断与用药适应证不符（如无感染诊断用抗菌药物）\n   · 诊断与检查项目不符（如无相应症状/体征却开专项检查）\n   · 性别与项目不符（男性患者出现妇科项目）\n   · 年龄与项目不符（成人开儿童专用项目）\n   · 部位与手术编码不符、主诊断与主手术不匹配\n\n4. 收费管理类\n   · 分解收费 / 重复收费（同一操作拆成多个项目、或已含在项目内的耗材另收）\n   · 超标准收费（超出当地医疗服务价格标准）\n   · 超医保支付标准（超出限价部分由患者自付需告知）\n   · 串换项目（用低价项目套高价项目收费）\n   · 打包项目重复计费\n\n5. 住院管理类\n   · 分解住院（同一疾病短期内多次出入院）\n   · 挂床住院 / 低标准入院（无住院指征收住院）\n   · 超长住院、住院期间无诊疗记录\n   · 门诊可解决的收住院\n\n──────────────────────────────\n【二、医生端自查清单（开单 / 写病历时就做）】\n\n□ 主要诊断写准：ICD 编码与实际病情一致，不用「待查」「不适」当主诊断\n□ 用药前看一眼说明书适应证与医保限定支付范围是否吻合\n□ 超说明书用药：必须有知情同意 + 病程记录写明理由\n□ 检查有指征：申请单填写临床意义，病程记录里体现「为什么查」\n□ 特殊级抗菌药物：会诊单、处方权限、用药前送检\n□ 复查频次异常：在病程记录里写清复查理由（如症状变化、疗效评估）\n□ 收费与实际操作一致：不多收、不拆收、不串换\n□ 住院有指征：入院记录写清收住院理由，病程记录每日有内容\n□ 出院带药不超量、不超疗程\n□ 转科/转院有记录，不出现「空档日」\n\n──────────────────────────────\n【三、被智能审核拦截 / 事后追回时怎么办】\n\n1. 先看拦截提示属于哪一类规则（限定支付范围？诊断不符？频次？收费？）\n2. 备齐申诉材料：\n   · 病历（入院记录、首次病程、日常病程、出院小结）\n   · 支持性检验检查结果\n   · 会诊记录、知情同意书、超说明书用药审批\n   · 收费明细与操作记录对应关系\n3. 申诉要点：说明「为什么必须这样做」，落到病历文字上——\n   病历里没写 = 视为没有（这是医保审核的基本原则）\n4. 时限：按当地医保局/医院医保办规定的申诉期限提交，逾期视为认可\n\n──────────────────────────────\n【四、提醒】\n\n· 各地医保政策差异很大（目录、限价、规则阈值都不一样），\n  本条为通用框架，具体以【当地医保局最新政策 + 本院医保办口径】为准。\n· 「两库」规则会随政策更新，建议每季度向医保办确认一次本院被拦截的 TOP 规则。\n\n【依据】国家医保局《医疗保障经办机构智能审核和监控知识库、规则库管理办法（试行）》\n        及各地医保智能监管实施细则（通用框架整理）\n"},"locator":{"file":"医疗文书/医疗文书导出_20261111.html","documentRow":332,"line":2028},"sourceHash":"c466f2764c8182aba31938a75abea847eab64e8882b2ae57a7b6c5436b544ec5","contentHash":"695ada845561c4892760aeb76f1a9367e6035d98d90448a0a06b81dec845ec58","pinyin":"yibaozhinengjianguan「liangku」guizesucha","initials":"ybznjg「lk」gzsc","quickFields":[]}]);